def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None or not isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for el, x in (s.get('composition') or {}).items():
        r = (props.get(el) or {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and isfinite(r) and r > 0:
            total += x * r * r * r
            weight += x
    return 4.0 * pi * total / (3.0 * v * weight) if weight > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    best = [inf] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                best[i] = min(best[i], d / (a + b))
    w = sum(occ[i] for i in range(n) if isfinite(best[i]))
    return sum(occ[i] * best[i] for i in range(n) if isfinite(best[i])) / w if w > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    en = [(props.get(t.get('element')) or {}).get('eneg') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    edges = s.get('neighbors') or []
    nearest = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and d is not None and 0 < d <= 6:
            nearest[i] = min(nearest[i], d)
    count = [0.0] * n
    total = [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6 and d <= 1.25 * nearest[i]:
            if en[j] is not None and isfinite(en[j]):
                count[i] += occ[j]
                total[i] += occ[j] * en[j]
    value = 0.0
    weight = 0.0
    for i in range(n):
        if count[i] > 0 and en[i] is not None and isfinite(en[i]):
            value += occ[i] * (en[i] - total[i] / count[i]) ** 2
            weight += occ[i]
    return sqrt(value / weight) if weight > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    amount = {}
    for i in range(n):
        el = sites[i].get('element')
        amount[el] = amount.get(el, 0.0) + occ[i]
    total = sum(occ)
    if total <= 0:
        return 0.0
    random_unlike = 1.0 - sum((x / total) ** 2 for x in amount.values())
    edges = s.get('neighbors') or []
    nearest = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and d is not None and 0 < d <= 6:
            nearest[i] = min(nearest[i], d)
    unlike = 0.0
    weight = 0.0
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6 and d <= 1.25 * nearest[i]:
            w = occ[i] * occ[j]
            weight += w
            if sites[i].get('element') != sites[j].get('element'):
                unlike += w
    return unlike / weight - random_unlike if weight > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    bulk = {}
    for i in range(n):
        el = sites[i].get('element')
        bulk[el] = bulk.get(el, 0.0) + occ[i]
    total = sum(occ)
    if total <= 0:
        return 0.0
    entropy = -sum((x / total) * log(x / total) for x in bulk.values() if x > 0)
    if entropy <= 1e-12:
        return 0.0
    edges = s.get('neighbors') or []
    nearest = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and d is not None and 0 < d <= 6:
            nearest[i] = min(nearest[i], d)
    shells = [{} for i in range(n)]
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6 and d <= 1.25 * nearest[i]:
            el = sites[j].get('element')
            shells[i][el] = shells[i].get(el, 0.0) + occ[j]
    value = 0.0
    weight = 0.0
    for i in range(n):
        count = sum(shells[i].values())
        if count > 0:
            value -= occ[i] * sum((x / count) * log(x / count) for x in shells[i].values() if x > 0)
            weight += occ[i]
    return value / (weight * entropy) if weight > 0 else 0.0

