def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    matrix = (s.get('lattice') or {}).get('matrix')
    if n == 0 or matrix is None:
        return 0.0
    matrix = np.asarray(matrix)
    props = s.get('element_properties') or {}
    en = [(props.get(t.get('element')) or {}).get('eneg') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    edges = s.get('neighbors') or []
    nearest = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and d is not None and 0 < d <= 6:
            nearest[i] = min(nearest[i], d)
    fields = np.zeros((n, 3))
    count = [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6 and d <= 1.25 * nearest[i]:
            if en[i] is not None and en[j] is not None and isfinite(en[i]) and isfinite(en[j]):
                a = sites[i].get('frac_coords')
                b = sites[j].get('frac_coords')
                image = edge.get('image')
                if a is not None and b is not None and image is not None:
                    v = np.dot(np.asarray([b[k] + image[k] - a[k] for k in range(3)]), matrix)
                    norm = sqrt(float(np.dot(v, v)))
                    if norm > 1e-10:
                        fields[i] += occ[j] * (en[j] - en[i]) * v / norm
                        count[i] += occ[j]
    value = 0.0
    weight = 0.0
    for i in range(n):
        if count[i] > 0:
            value += occ[i] * sqrt(float(np.dot(fields[i], fields[i]))) / count[i]
            weight += occ[i]
    return value / weight if weight > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    atomic = {}
    numerator = 0.0
    denominator = 0.0
    for el, x in (s.get('composition') or {}).items():
        p = props.get(el) or {}
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if x is not None and x > 0 and ion is not None and affinity is not None and isfinite(ion) and isfinite(affinity):
            hardness = ion - affinity
            if hardness > 1e-6:
                chi = 0.5 * (ion + affinity)
                atomic[el] = (chi, hardness)
                numerator += x * chi / hardness
                denominator += x / hardness
    if denominator <= 0:
        return 0.0
    mu = numerator / denominator
    charges = {el: (mu - pair[0]) / pair[1] for el, pair in atomic.items()}
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    q = [charges.get(t.get('element'), 0.0) for t in sites]
    total = sum(occ)
    if total <= 0:
        return 0.0
    value = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            value += occ[i] * occ[j] * q[i] * q[j] * (1.0 - d / 6.0) ** 2 / d
    return 0.5 * 14.3996 * value / total

def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    entries = []
    numerator = 0.0
    denominator = 0.0
    weight = 0.0
    for el, x in (s.get('composition') or {}).items():
        p = props.get(el) or {}
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if x is not None and x > 0 and ion is not None and affinity is not None and isfinite(ion) and isfinite(affinity):
            hardness = ion - affinity
            if hardness > 1e-6:
                chi = 0.5 * (ion + affinity)
                entries.append((x, chi, hardness))
                numerator += x * chi / hardness
                denominator += x / hardness
                weight += x
    if denominator <= 0 or weight <= 0:
        return 0.0
    mu = numerator / denominator
    return 0.5 * sum(x * (chi - mu) ** 2 / hardness for x, chi, hardness in entries) / weight
